from bulk_common import *
import pandas as pd
from scipy.spatial.transform import Rotation

def main():
 inv=read(OUT/'inventory.json');cfg=dict(version=OUT.name,scope='All191 previously locked nonoverlapping G1 near-person intervals/21recordings/154sourceclips. Reprocess external_box SAM2 masks from20261020 with improved association;0new raw video frames. Retain existing exclusions and manual review flags.',annotation='No SAM2 weights/inference changes. Reuse frozen final candidates, anonymize ID, run original full geometry association and improved partial-appearance in separate arms. Last-before-current camera R/translation plus surface-depth proxy, CV Kalman, Hungarian, old gates/weights/lifecycle. Frozen DINO global+foreground local patches and reliable gallery from20261028. No future states in association; SAM/MPS upstream offline.',depth='All3850candidate-positive frames;613reuse3237new. Official sequential512 vitl32/32iterations/LR1px;prior timing and quality rules unchanged. Re-measure exact current masks. Missing/invalid measurements retained with explicit flags and rotation fallback; no invented depth.',packaging='Keep all masks/IDs and per-frame quality flags. Export every contiguous21-frame target window without mandatory head/tail trim; additionally flag all quality criteria using existing frame_rule and area jumps. Quality subset is separate, never delete full annotated data. Carry all manual warnings. No automatic forecast training or baseline replacement with this bulk dataset.',splits='Preserve recording/time provenance and existing six heldout folds. Future use must exclude BOTH test and validation recordings including pretrained models. Duplicate timestamps inventoried; do not call window counts independent people/scenes.',validation='Compare original/global versus partial association using source-ID agreement only, not human GT. Deterministic prefix/order replay on fixed one interval per recording; all-mask centers/RLE/data association audit. Visual overview every interval and target temporal sheets for all continuous-window identities. Review flags do not tune algorithms.',preserve='Old labels/models/results/PPT/CVAT unchanged. D experiment uses only old117 and locked412, not these newly generated labels.')
 if (OUT/'protocol.json').exists():assert read(OUT/'protocol.json')==cfg
 else:write(OUT/'protocol.json',cfg);write(ROOT/'plans/G1_BULK_ASSOCIATION_20261029.txt',cfg)
 protected=read(OUT/'source_hashes.json');count=0;maxage=0.
 for rec in sorted({c['recording'] for c in inv['clips']}):
  path=ROOT/f'data/Aria/raw_vrs/mps_{rec}_vrs/slam/closed_loop_trajectory.csv';protected[str(path.relative_to(ROOT))]=sha(path);cols=['tracking_timestamp_us','graph_uid','quality_score']+[f't{a}_world_device' for a in 'xyz']+[f'q{a}_world_device' for a in 'xyzw'];df=pd.read_csv(path,usecols=cols);ns=df.tracking_timestamp_us.to_numpy(np.int64)*1000;assert (np.diff(ns)>0).all()
  for c in inv['clips']:
   if c['recording']!=rec:continue
   ref=dict(np.load(ROOT/c['input']/'reference.npz'));ts=ref['times_ns'][c['lo']:c['hi']];ii=np.searchsorted(ns,ts,side='right')-1;assert (ii>=0).all();age=ts-ns[ii];assert ((age>=0)&(age<=30000000)).all();assert (df.quality_score.to_numpy()[ii]>=.5).all();assert len(set(df.graph_uid.to_numpy()[ii]))==1;rd=Rotation.from_quat(df[[f'q{a}_world_device' for a in 'xyzw']].to_numpy()[ii]).as_matrix();ext=ref['T_device_camera'];R=rd@ext[:3,:3];pos=df[[f't{a}_world_device' for a in 'xyz']].to_numpy()[ii]+rd@ext[:3,3];origin=pos[0].copy();pos-=origin;dest=OUT/'poses'/f'{c["clip"]}.npz';dest.parent.mkdir(parents=True,exist_ok=True);np.savez_compressed(dest,R=R,c=pos,K=ref['K'],times_ns=ts,selected_mps_ns=ns[ii],world_origin=origin);maxage=max(maxage,float(age.max()/1e6));count+=len(ts)
  print('POSE',rec,count,flush=True)
 write(OUT/'source_hashes.json',protected);write(OUT/'pose_complete.json',dict(passed=True,frames=count,max_selected_age_ms=maxage,all_last_before_exposure=True))
